/* THROWAWAY — six-scale visual study. All edits stay in memory. */
'use strict';
const LEVELS=['world','continent','region','metro','campus','facility'];
const NAMES={A:'Editorial atlas',B:'Evidence desk',C:'Map focus'};
const REGIONS=['North America','Europe','Asia','Middle East','Other'];
const NC='amazon-anthropic-new-carlisle',HELIOS='coreweave-helios';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,n=0)=>Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:n}):'Not quantified';
const cap=x=>x.charAt(0).toUpperCase()+x.slice(1);
const region=s=>['United States','Canada','Mexico'].includes(s.country)?'North America':['United Kingdom','Norway','Sweden','Finland','Denmark','Iceland','France','Germany','Spain','Portugal','Italy','Ireland','Netherlands','Switzerland','Poland','Austria','Belgium'].includes(s.country)?'Europe':['China','Japan','South Korea','India','Singapore','Malaysia','Indonesia','Taiwan','Vietnam','Thailand'].includes(s.country)?'Asia':['United Arab Emirates','Saudi Arabia','Israel','Qatar'].includes(s.country)?'Middle East':'Other';
const known=(s,phase)=>['reviewed-model','archive'].includes(s.review)&&typeof s[phase]?.it_mw==='number';
const modelPower=(s,phase,unit='MW')=>known(s,phase)?fmt(s[phase].it_mw)+' '+unit:'Not quantified';
const sum=(sites,phase='snapshot')=>({count:sites.length,known:sites.filter(s=>known(s,phase)).length,mw:sites.filter(s=>known(s,phase)).reduce((n,s)=>n+s[phase].it_mw,0)});
let state,images=new Map(),camera=null,drawn=[],drag=null;
const memory={notes:{},shelf:[],compare:[NC,HELIOS],layers:{locations:true,research:true,labels:true,electricity:false},panel:null,topic:'overview'};
function readState(){const p=new URLSearchParams(location.search);state={variant:['A','B','C'].includes(p.get('variant'))?p.get('variant'):'A',scale:LEVELS.includes(p.get('scale'))?p.get('scale'):'world',site:DATA.sites.some(s=>s.id===p.get('site'))?p.get('site'):NC,scene:p.get('scene')||'',feature:p.get('feature')||'',region:REGIONS.includes(p.get('region'))?p.get('region'):'all',phase:p.get('phase')==='target'?'target':'snapshot',q:p.get('q')||'',inspect:p.get('inspect')==='1'};camera=null;}
function go(update,replace=false){Object.assign(state,update);const p=new URLSearchParams();for(const [k,v] of Object.entries(state))if(v!==''&&v!==false)p.set(k,v===true?'1':v);history[replace?'replaceState':'pushState'](null,'',location.pathname+'?'+p);camera=null;closePanel();render();window.scrollTo({top:0,behavior:'instant'});}
function project(){return DATA.sites.find(s=>s.id===state.site)||DATA.sites.find(s=>s.id===NC);}
function scene(){const rows=DATA.scenes.filter(s=>s.project_id===state.site);return rows.find(s=>s.id===state.scene)||rows[0];}
function feature(){const m=scene();return m?.features.find(f=>f.id===state.feature)||(state.scale==='facility'?m?.features[0]:null);}
function scope(){let xs=DATA.sites.filter(s=>Number.isFinite(s.lon)&&Number.isFinite(s.lat));if(state.q)xs=xs.filter(s=>(s.name+' '+s.location+' '+s.owner_label).toLowerCase().includes(state.q.toLowerCase()));if(state.region!=='all')xs=xs.filter(s=>region(s)===state.region);if(state.scale==='continent'&&state.region==='all')xs=xs.filter(s=>['North America','Europe'].includes(region(s)));if(state.scale==='region')xs=xs.filter(s=>s.lon>=-98&&s.lon<=-66&&s.lat>=27&&s.lat<=50);if(state.scale==='metro')xs=xs.filter(s=>s.lon>=-87.98&&s.lon<=-86.20&&s.lat>=41.36&&s.lat<=42.19);if(['campus','facility'].includes(state.scale))xs=[project()];return xs;}
function regionalRows(){return REGIONS.map(name=>({name,...sum(scope().filter(s=>region(s)===name),'target')})).filter(r=>r.count).sort((a,b)=>b.mw-a.mw||b.count-a.count);}
function sourceIds(s=project()){return [...new Set([...DATA.observations,...DATA.facts,...DATA.relationships].filter(r=>r.site_id===s.id&&r.review_status==='accepted').map(r=>r.source_id))];}
function source(id){return DATA.sources.find(s=>s.id===id);}
function powerRows(){return DATA.observations.filter(r=>r.site_id===state.site&&r.review_status==='accepted'&&r.metric==='power'&&r.boundary==='critical_it'&&['Phase I','Phase II','Phases I–III'].includes(r.scope));}
function headline(){if(state.scale==='world')return ['A global view<br>of compute capital.','Follow the places, power and counterparties behind AI.'];if(state.scale==='continent')return [state.region==='all'?'North America ↔ Europe.<br>The physical network behind AI.':esc(state.region)+'.<br>Follow the compute footprint.','A partial research collection. Explore the projects behind the geographic pattern.'];if(state.scale==='region')return ['The Midwest and East Coast,<br>from power to compute.','Choose a project. See its dated estimates, disclosures and source boundaries.'];if(state.scale==='metro')return ['Chicago to New Carlisle.','Power, land and compute meet at the local scale.'];return [esc(project().name)+(state.scale==='campus'?' campus.':' — physical feature.'),'Inspect historical geometry alongside dated project evidence.'];}
function scales(){return `<nav class="scales" aria-label="Design scale">${LEVELS.map((k,i)=>`<button data-scale="${k}" class="${state.scale===k?'active':''}"><small>${String(i+1).padStart(2,'0')}</small>${cap(k)}</button>`).join('')}<button class="scale-end" data-panel="search">Find a project ↗</button></nav>`;}
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-symbol"></div><div><strong>COMPUTE</strong><small>ATLAS</small></div></div><div class="eyebrow">Infrastructure & capital</div>${[['⌂','The landscape','world'],['▦','Facility directory','inventory'],['◫','Company universe','companies'],['⌘','Contracts & connections','relationships'],['↗','Investment lens','investment'],['▤','Research library','sources']].map(([icon,title,id])=>`<button class="nav-item ${id==='world'?'active':''}" ${id==='world'?'data-scale="world"':'data-panel="'+id+'"'}><span>${icon}</span><b style="font-weight:400">${title}</b></button>`).join('')}<div class="side-divider"></div><div class="eyebrow">Research tools</div><button class="nav-item" data-panel="compare"><span>⇄</span><b>Compare projects</b></button><button class="nav-item" data-panel="shelf"><span>☆</span><b>Research shelf</b></button><button class="nav-item" data-panel="review"><span>◷</span><b>Sources & updates</b></button><div class="sidebar-foot"><div class="eyebrow"><i class="live-dot"></i>Dated research collection</div><p>Estimates, disclosures and physical features retain their own sources.</p><button class="text-link" data-panel="coverage">Reading the evidence ↗</button></div></aside>`;}
function topbar(){return `<header class="topbar"><button class="mobile-menu" aria-label="Open design navigation" data-menu>☰</button><div class="crumbs"><button data-scale="world">The landscape</button>${state.scale!=='world'?'<span>›</span><button data-scale="'+state.scale+'">'+(['campus','facility'].includes(state.scale)?esc(project().name):cap(state.scale))+'</button>':''}${state.scale==='facility'?'<span>›</span><span>Roof evidence</span>':''}</div><button class="search" data-panel="search"><span>⌕</span><span class="search-label">Search a project, company or source…</span><span class="key">⌘ K</span></button><div class="dataset"><small>RESEARCH SNAPSHOT</small><b>10 OCT 2026</b></div><button data-review-toggle aria-label="Show or hide design controls">Design</button><button data-panel="coverage" aria-label="Evidence help">?</button></header>`;}
function hero(){const [title,description]=headline(),physical=['campus','facility'].includes(state.scale);return `<section class="hero"><div><div class="eyebrow">${physical?'Facility & campus':'Compute, from the ground up'}</div><h1>${title}</h1>${physical?'<p class="location">⌖ '+esc(project().location)+' · '+esc(project().country)+'</p>':''}</div><div class="hero-aside"><p class="intro-copy">${description}</p><button class="primary" ${physical?'data-save':'data-tour'}>${physical?(memory.shelf.includes(state.site)?'✓ On research shelf':'Add to research shelf +'):'Explore the atlas →'}</button></div></section>`;}
function metrics(){const xs=scope(),a=sum(xs,state.phase),t=sum(xs,'target');let rows=[[a.known?fmt(a.mw/1000,3)+' GW':'—','Dated '+state.phase+' IT estimate','Partial, mixed-vintage model subtotal'],[fmt(a.count),'Named research projects','Approximate cartographic anchors'],[fmt(a.known),'Comparable IT estimates',fmt(a.count-a.known)+' native / unknown records'],[t.known?fmt(t.mw/1000,3)+' GW':'—','Dated target IT estimate','Independent end-state; not incremental']];if(['campus','facility'].includes(state.scale)){const p=project(),m=scene();rows=[[modelPower(p,'snapshot','MW'),'Independent snapshot estimate',p.snapshot?.date||'Date not supplied'],[modelPower(p,'target','MW'),'Independent target estimate',p.target?.date||'Date not supplied'],[m?String(m.features.length):'—','Interpreted roofs in this scene',m?m.image.acquired_at+' historical imagery':'No accepted scene'],[String(sourceIds().length),'Primary project documents','Original publication dates retained']];}return `<section class="metrics" aria-label="Scope summary">${rows.map(([v,l,n])=>`<div class="metric"><div class="label">${esc(l)}</div><strong>${esc(v)}</strong><p>${esc(n)}</p></div>`).join('')}</section>`;}
function map(physical=false){const title=physical?(scene()?.component||'Helios historical scene'):state.scale==='world'?'Global compute map':state.scale==='continent'?'Continental system':state.scale==='region'?'US East & Midwest':'Chicago–Northern Indiana';return `<section class="map ${physical?'physical-map':''}" aria-label="${esc(title)}"><canvas id="design-map" tabindex="0" aria-label="${physical?'Historical aerial with selectable interpreted roofs':'Source-derived map; click a project to inspect'}"></canvas><div class="map-caption"><div><h3>${esc(title)}</h3><p>${physical?'Historical aerial · interpreted roof outlines':scope().length+' research anchors · '+state.phase+' estimates'}</p></div><div>${physical?'<button class="map-toggle active" data-mapmode="image">Aerial</button><button class="map-toggle" data-panel="layers">Layers</button>':['snapshot','target'].map(p=>`<button class="map-toggle ${p===state.phase?'active':''}" data-phase="${p}">${cap(p)}</button>`).join('')}</div></div>${physical?`<div class="historical-tag">${esc(scene()?.image.acquired_at||'UNAVAILABLE')} IMAGERY · HISTORICAL CONTEXT</div>`:'<div class="map-subcontrols"><button data-panel="layers">Layers ▱</button><button data-panel="filters">Refine view +</button><button data-panel="share">Share ↗</button></div>'}<div class="legend">${!physical?'<span style="color:#9aaeb5">· OSM locations · no capacity implied</span>':''}<span><i></i>${physical?'Interpreted roof · selected':'Reviewed / mixed estimate cluster'}</span><span><i></i>${physical?'Other interpreted roof':'Imported estimate'}</span><span><i></i>${physical?'No phase or IT allocation':'Native-unit / unquantified'}</span></div>${physical?'<div class="image-boundary"><strong>'+esc(feature()?.name||'Select an interpreted roof')+'</strong><br>Image '+esc(scene()?.image.acquired_at)+' · historical interpretation, not current operations.</div>':''}<div class="map-footer">${physical?'<button class="pill" data-frame>Frame '+(feature()?'selected roof':'scene')+'</button><button class="pill" data-panel="image">Image & geometry sources ↗</button>':['all','North America','Europe','Asia','Middle East'].map(r=>`<button class="pill ${state.region===r?'active':''}" data-region="${r}">${r==='all'?'All':r==='North America'?'N. America':r==='Middle East'?'Middle East':r}</button>`).join('')}<div class="tools"><button data-labels aria-label="Toggle map labels">Aa</button><button data-zoom="in" aria-label="Zoom map">+</button><button data-zoom="out" aria-label="Zoom map">−</button><button data-frame aria-label="Frame scope">⛶</button></div></div><div id="marker-layer"></div></section>`;}
function globalRail(){const a=sum(scope(),state.phase),rows=regionalRows(),max=Math.max(1,...rows.map(r=>r.mw)),candidate=scope().find(s=>DATA.scenes.some(m=>m.project_id===s.id))||scope()[0],m=DATA.scenes.find(x=>x.project_id===candidate?.id);return `<aside class="rail"><section class="rail-section"><div class="eyebrow">01 / The global takeaway</div><h2>Compute is a<br>physical asset class.</h2><p>${a.count} named projects across ${new Set(scope().map(s=>s.country)).size} countries.</p><div class="coverage-strip"><i style="width:${a.count?a.known/a.count*100:0}%"></i></div><div class="coverage-label"><span>${a.known} IT estimates</span><span>${a.count-a.known} native / unknown</span></div></section><section class="rail-section"><div class="eyebrow">02 / Projected buildout</div><h2>Where capacity<br>is being planned.</h2><div class="ranks">${rows.map(r=>`<button class="rank" data-regional-entry="${r.name}"><div class="rank-title"><span>${r.name}</span><strong>${r.known?fmt(r.mw/1000,2)+' GW':'Not quantified'} ↗</strong></div><div class="rank-bar"><i style="width:${r.mw/max*100}%"></i></div><small>${r.known} target estimates · ${r.count-r.known} unquantified</small></button>`).join('')||'<p>No matching projects.</p>'}</div><p class="footnote">Partial, mixed-vintage targets. No market share or live capacity implied.</p></section><section class="rail-section"><div class="eyebrow">03 / From the globe to the ground</div><h2>Go inside a campus.</h2>${candidate?`<button class="preview-image" data-preview="${candidate.id}">${m?`<img src="${m.image.embedded}" alt="Historical aerial of ${esc(candidate.name)}">`:""}<span>${esc(candidate.name)} ↗</span><small>${m?esc(m.image.acquired_at)+" IMAGERY":"NO REVIEWED IMAGE"}</small></button>`:"<p>No project in this scope.</p>"}<p class="footnote">${m?"Historical roofs, separate project disclosures and original sources.":"Project evidence remains accessible. Imagery is not established."}</p></section></aside>`;}
function selectedRail(){const p=project(),a=p[state.phase];return `<aside class="rail"><section class="rail-section selected-card"><div class="eyebrow">01 / Selected project</div><h2>${esc(p.name)}.</h2><p>${esc(p.location)}</p><div class="status-row"><span class="tag">Independent model</span><span class="pill">${esc(a?.date||'Not quantified')}</span></div><div class="quantity">${modelPower(p,state.phase)}</div><p>${cap(state.phase)} IT estimate · project scope</p><div class="data-row"><span>Hardware / cloud</span><b>${esc(p.owner_label)}</b></div><div class="data-row"><span>Location precision</span><b>Research anchor</b></div><button class="primary" data-preview="${p.id}">Explore this campus →</button><p class="footnote">Dated independent estimate; no operator-confirmed live load.</p></section><section class="rail-section"><div class="eyebrow">02 / Project evidence</div><h2>Follow the original source.</h2><p>Compare the model, disclosure and physical evidence with their dates attached.</p><div class="identity-trail"><button class="text-link" data-panel="sources">Sources ↗</button><button class="text-link" data-compare-add>Compare +</button><button class="text-link" data-panel="relationships">Counterparties ↗</button></div></section><section class="rail-section"><div class="eyebrow">03 / Other research projects</div><div class="context-list">${scope().filter(s=>s.id!==p.id).slice(0,2).map(s=>`<button data-project="${s.id}">${esc(s.name)} ↗<span>${esc(s.location)} · ${known(s,state.phase)?fmt(s[state.phase].it_mw)+' MW estimate':'IT not quantified'}</span></button>`).join('')||'<p>No other named research projects in this frame.</p>'}</div><button class="text-link" style="margin-top:10px" data-panel="inventory">Separate location inventory ↗</button></section></aside>`;}
function physicalRail(){const p=project(),m=scene(),f=feature(),rows=powerRows();return `<aside class="rail"><section class="rail-section selected-card"><div class="eyebrow">01 / ${f?'Selected physical feature':'Campus dossier'}</div><h2>${esc(f?.name||p.name)}.</h2><p>${esc(p.name)} · ${esc(m?.component||p.location)}</p><div class="status-row"><span class="tag">${f?'Interpreted roof':'Historical context'}</span><span class="pill">${esc(m?.image.acquired_at||'Image unavailable')}</span></div>${f?`<div class="feature-quantity">≈ ${fmt(f.derived_outline_area?.rounded_m2||0)} m²</div><p>Interpreted roof outline area · not floor area</p>`:`<div class="data-row"><span>Interpreted roofs</span><b>${m?.features.length||'Not available'}</b></div><div class="data-row"><span>Components in this project</span><b>${DATA.scenes.filter(x=>x.project_id===p.id).length||'Not available'}</b></div>`}<div class="missing-match"><strong>Phase / IT assignment not established</strong><p>The roof is a physical source feature. Project power disclosures have a separate scope.</p></div><button class="text-link" data-panel="image">Image, interpretation & identity ↗</button></section><section class="rail-section"><div class="eyebrow">02 / Dated power evidence</div><h2>${rows.length?'Power has more<br>than one boundary.':'Estimates retain<br>their own dates.'}</h2>${rows.length?rows.map(r=>`<div class="data-row"><span>${esc(r.scope)}<small class="muted" style="display:block;font-size:8px">${esc(r.status.replaceAll('_',' '))} · ${esc(r.as_of)}</small></span><b>${fmt(r.value)} MW IT</b></div>`).join(''):`<div class="data-row"><span>Snapshot model · ${esc(p.snapshot?.date)}</span><b>${modelPower(p,'snapshot','MW')}</b></div><div class="data-row"><span>Target model · ${esc(p.target?.date)}</span><b>${modelPower(p,'target','MW')}</b></div>`}<p class="footnote">${rows.length?'526 MW includes the disclosed phases; it is not an additional increment.':'Independent mixed-date estimates; no building allocation.'}</p><button class="text-link" data-topic="energy">Inspect power & phases ↗</button></section><section class="rail-section"><div class="eyebrow">03 / Counterparties</div>${DATA.relationships.filter(r=>r.site_id===p.id&&r.review_status==='accepted').slice(0,3).map(r=>`<div class="role-row"><span>${esc(r.role)}</span><b>${esc(DATA.companies.find(c=>c.id===r.company_id)?.name||r.company_id)}</b></div>`).join('')}<button class="text-link" style="margin-top:12px" data-panel="relationships">Roles, dates & source documents ↗</button></section></aside>`;}
function tabs(){return `<nav class="project-tabs" aria-label="Project research topic">${[['overview','Overview'],['energy','Power & phases'],['technical','Technical design'],['timeline','Development'],['relationships','Counterparties'],['investment','Investment'],['sources','Sources & evidence']].map(([k,n])=>`<button data-topic="${k}" class="${memory.topic===k?'active':''}">${n}</button>`).join('')}</nav>`;}
function sourceRows(ids=sourceIds()){return ids.slice(0,4).map(id=>{const s=source(id);return s?`<button class="source-row" data-source="${id}"><i>▤</i><span><b>${esc(s.publisher)} · ${esc(s.title)}</b><small>${esc(s.published_at||'Publication date not stated')} · ${esc(s.kind||'Primary document')}</small></span><span>${esc(id)} ↗</span></button>`:'';}).join('')||'<p class="empty">No project-specific primary documents in this prototype subset.</p>';}
function evidenceBelow(){return `<div class="evidence-below"><section class="section"><div class="eyebrow">04 / Sources & evidence</div>${sourceRows()}<button class="text-link" style="margin-top:12px" data-panel="sources">All project documents & claims ↗</button></section><section class="section"><div class="eyebrow">05 / Analyst notes</div><h3>What would change your view?</h3><textarea class="note" data-note aria-label="Session-only analyst note" placeholder="A missing phase match, the next permit, a different power boundary…">${esc(memory.notes[state.site]||'')}</textarea><div class="note-footer"><span>Design session only · no saved evidence</span><button data-save class="text-link">${memory.shelf.includes(state.site)?'✓ On shelf':'Add to research shelf +'}</button></div></section></div>`;}
function topicContent(){if(memory.topic==='overview')return evidenceBelow();if(memory.topic==='energy')return `<section class="section detail-content"><div class="eyebrow">Power & phases / Project scope</div><h3>Read each quantity with its boundary.</h3><div class="evidence-below"><div>${powerRows().length?powerRows().map(r=>`<div class="power-row"><span>${esc(r.scope)}<small>${esc(r.status.replaceAll('_',' '))}</small></span><div class="bar"><i style="width:${r.value/526*100}%"></i></div><strong>${fmt(r.value)} MW<small>${esc(r.as_of)}</small></strong></div>`).join(''):`<div class="data-row"><span>Snapshot model</span><b>${modelPower(project(),'snapshot','MW')} · ${esc(project().snapshot?.date)}</b></div><div class="data-row"><span>Target model</span><b>${modelPower(project(),'target','MW')} · ${esc(project().target?.date)}</b></div>`}<p class="small muted">Separate scopes are not additive. Power is not assigned to a roof.</p></div><div class="planned-feature"><div class="eyebrow">Designed missing workflow</div><h3>Match a building to a phase.</h3><p>A source-backed proposal must identify the building, phase, document locator and date. A reviewed correspondence is required before a roof receives a power quantity.</p><button class="pill" disabled>Reviewed assignment unavailable</button></div></div></section>`;const facts=DATA.facts.filter(r=>r.site_id===state.site&&r.review_status==='accepted');if(memory.topic==='timeline')return `<section class="section detail-content"><div class="eyebrow">Development / source chronology</div><h3>One project. Several dates.</h3>${project().timeline?.length?project().timeline.map(r=>`<div class="timeline-row"><time>${esc(r.date)}</time><div><b>${esc(r.label)}</b><small>${esc(r.kind)}${r.mw!=null?' · '+fmt(r.mw)+' MW':''} · independent model chronology</small></div></div>`).join(''):'<p class="empty">No independent model timeline in this project. The dated primary phase disclosures remain available under Power & phases.</p>'}</section>`;if(['relationships','investment','sources'].includes(memory.topic))return `<section class="section detail-content"><div class="eyebrow">${esc(memory.topic)} / Project research</div><h3>Trace the claim to its original source.</h3>${sourceRows()}<button class="text-link" style="margin-top:15px" data-panel="${memory.topic}">Open ${esc(memory.topic)} details ↗</button></section>`;return `<section class="section detail-content"><div class="eyebrow">Technical design / Dated claims</div><h3>Disclosures stay separate from interpretation.</h3><div class="claim-grid">${facts.slice(0,6).map(r=>`<article class="claim"><b>${esc(r.label)}</b><p>${esc(r.value)}</p><small>${esc(r.as_of||'Undated')} · ${esc(r.source_id)}</small></article>`).join('')||'<p class="empty">No reviewed technical claim in this prototype subset.</p>'}</div></section>`;}
function mapColumn(){const physical=['campus','facility'].includes(state.scale),m=scene();return `<div class="map-wrap">${physical?`<div class="component-line"><span>Independent physical source · ${esc(project().name)}</span><label>Component <select data-component aria-label="Campus component">${DATA.scenes.filter(s=>s.project_id===state.site).map(s=>`<option value="${s.id}" ${s.id===m?.id?'selected':''}>${esc(s.component||'Helios original roof')} · ${esc(s.image.acquired_at)}</option>`).join('')}</select></label></div>`:''}${map(physical)}<div class="map-attribution"><span>${physical?esc(m?.image.short_publisher||m?.image.publisher||'Historical imagery')+' · '+esc(m?.image.license):'Natural Earth · source-derived reference geography'}</span><button data-panel="coverage">Map & evidence boundary ↗</button></div>${physical?'<div class="roof-picker">'+(m?.features||[]).map(f=>`<button data-feature="${f.id}" class="${feature()?.id===f.id?'active':''}">${esc(f.name)}</button>`).join('')+'</div>'+topicContent():''}</div>`;}
function editorial(){const physical=['campus','facility'].includes(state.scale),selected=['region','metro'].includes(state.scale)||state.inspect;return hero()+scales()+(physical?tabs():'')+`<div class="layout-a">${mapColumn()}${physical?physicalRail():selected?selectedRail():globalRail()}${!physical?metrics():''}</div>`+(physical?metrics():'')+`<div class="boundary-row"><span>${physical?'Historical source features and project evidence are independent.':'Dated named-project collection · no global census or available-capacity claim.'}</span><button class="text-link" data-panel="coverage">Sources, coverage & methodology ↗</button></div>${!physical?`<div class="discovery"><span><strong>Follow the next scale.</strong> Select a project, inspect its evidence, then enter its campus.</span><button data-panel="search">Browse ${scope().length} research projects ↗</button></div>`:''}`;}
function workbench(){const rows=scope().slice().sort((a,b)=>(b[state.phase]?.it_mw||0)-(a[state.phase]?.it_mw||0)).slice(0,8),p=project(),a=sum(scope(),state.phase);return `<section class="hero"><div><div class="eyebrow">Compute / research workspace</div><h1>Find the evidence.<br>Then follow the asset.</h1></div><div class="hero-aside"><p class="intro-copy">A record-first view for comparing project estimates, physical identity and dated sources.</p><button class="primary" data-panel="compare">Compare projects ⇄</button></div></section>`+scales()+`<div class="workbench-heading"><p>${scope().length} projects · ${a.known} comparable ${state.phase} IT estimates · ${a.count-a.known} native / unknown</p><button class="text-link" data-panel="filters">Refine collection +</button></div><div class="workbench-grid"><section class="workbench-table"><div class="record-header"><span>PROJECT / LOCATION</span><span>SNAPSHOT</span><span>TARGET</span><span>↗</span></div>${rows.map(s=>`<button class="record-row ${s.id===p.id?'selected':''}" data-project="${s.id}"><div><b>${esc(s.name)}</b><small>${esc(s.location)} · ${esc(s.owner_label)}</small></div><span>${known(s,'snapshot')?fmt(s.snapshot.it_mw)+' MW':'Native'}<small>${esc(s.snapshot?.date||'Unquantified')}</small></span><span>${known(s,'target')?fmt(s.target.it_mw)+' MW':'Unknown'}<small>${esc(s.target?.date||'Unquantified')}</small></span><span class="record-check">${s.id===p.id?'●':'↗'}</span></button>`).join('')}<div class="boundary-row"><span>Sorted by ${state.phase} estimate · no summed company fleet</span><button class="text-link" data-panel="inventory">Inventory identity review ↗</button></div></section><section class="workbench-map">${map(['campus','facility'].includes(state.scale))}<div class="workbench-inspector"><div class="eyebrow">Selected project</div><h2 style="margin:8px 0">${esc(p.name)}.</h2><p class="small muted">${esc(p.location)} · ${esc(p.owner_label)}</p><div class="data-row"><span>Snapshot model</span><b>${modelPower(p,'snapshot','MW')}</b></div><div class="data-row"><span>Target model</span><b>${modelPower(p,'target','MW')}</b></div><p class="small muted" style="margin:12px 0">Dates and boundaries are independent. Nearby directory records are proposed identity matches until reviewed.</p><button class="primary" data-preview="${p.id}">Inspect campus & sources →</button></div></section></div><div class="workbench-footer"><div><strong>${fmt(a.mw/1000,3)} GW</strong><small>Partial ${state.phase} IT subtotal</small></div><div><strong>${DATA.catalog_count.toLocaleString()}</strong><small>OSM location records · separate inventory</small></div><div><strong>${sourceIds().length}</strong><small>Selected project primary documents</small></div></div>`;}
function immersive(){const p=project();return `<div class="immersive">${map(['campus','facility'].includes(state.scale))}<div class="immersive-title"><div class="eyebrow">Compute / spatial explorer</div><h1>From the world.<br>To the ground.</h1><p>Select a geographic pattern. Inspect the project. Trace the evidence.</p></div>${scales()}<aside class="immersive-sheet"><div class="eyebrow">Selected project / research anchor</div><h2>${esc(p.name)}.</h2><p>${esc(p.location)} · ${esc(p.owner_label)}</p><div class="data-row"><span>Snapshot model</span><b>${modelPower(p,'snapshot','MW IT')}</b></div><div class="data-row"><span>Target model</span><b>${modelPower(p,'target','MW IT')}</b></div><p style="margin-top:13px">Independent dated estimates. Open the exact physical scene and source documents.</p><button class="primary" data-preview="${p.id}">Enter this campus →</button><button class="text-link" style="margin-top:12px" data-panel="sources">Read the evidence ↗</button></aside><div class="immersive-bottom">${metrics()}</div></div>`;}
function reviewBar(){document.getElementById('review-bar').innerHTML=`<div class="review-title">DESIGN STUDY<br>NO PRODUCTION CHANGES</div><button class="review-arrow" data-variant-arrow="-1" aria-label="Previous design">←</button><div class="review-variants">${Object.keys(NAMES).map(k=>`<button data-variant="${k}" class="${state.variant===k?'active':''}">${k} · ${NAMES[k]}</button>`).join('')}</div><button class="review-arrow" data-variant-arrow="1" aria-label="Next design">→</button><button class="review-export" data-panel="review">Design notes</button><div class="review-state">${esc(state.variant+' / '+state.scale+' / '+state.region+' / '+state.phase)}<br>${esc(project().name+' / '+(feature()?.name||'no roof selected')+' / topic: '+memory.topic+' / '+(state.q||'no text filter')+' / in-memory state')}</div>`;}
function render(){document.body.className='variant-'+state.variant.toLowerCase();document.getElementById('prototype').innerHTML=`<div class="shell">${sidebar()}<main class="main">${topbar()}${state.variant==='A'?editorial():state.variant==='B'?workbench():immersive()}</main></div>`;reviewBar();drawMap();}
function projectPoint(lon,lat,w,h){const r=Math.min(w*.42,h*.42),cx=w*(state.variant==='C'?.47:.51),cy=h*(state.variant==='C'?.54:.52);let angle=camera?.lon??(state.region==='Europe'?10:state.region==='Asia'?105:state.region==='Middle East'?47:state.region==='North America'?-97:-35),tilt=camera?.lat??(state.scale==='continent'?40:25),zoom=camera?.zoom??(state.scale==='continent'?1.3:1);const la=lat*Math.PI/180,lo=(lon-angle)*Math.PI/180,t=tilt*Math.PI/180;return {x:cx+r*zoom*Math.cos(la)*Math.sin(lo),y:cy-r*zoom*(Math.cos(t)*Math.sin(la)-Math.sin(t)*Math.cos(la)*Math.cos(lo)),z:Math.sin(t)*Math.sin(la)+Math.cos(t)*Math.cos(la)*Math.cos(lo),r:r*zoom,cx,cy};}
function flatPoint(lon,lat,w,h){let bounds=state.scale==='metro'?[-87.98,41.36,-86.20,42.19]:[-98,27,-66,50];const merc=y=>Math.log(Math.tan(Math.PI/4+y*Math.PI/360)),[x0,y0,x1,y1]=bounds,pad=state.scale==='metro'?65:53,scale=Math.min((w-30)/(x1-x0),(h-pad-60)/(merc(y1)-merc(y0))*Math.PI/180)*(camera?.zoom||1),cx=w*.5,cy=(h+pad-50)*.5;return {x:cx+(lon-(x0+x1)/2)*scale,y:cy-(merc(lat)-(merc(y0)+merc(y1))/2)*scale*180/Math.PI,z:1};}
function drawMap(){const canvas=document.getElementById('design-map');if(!canvas)return;const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const c=canvas.getContext('2d');c.scale(dpr,dpr);drawn=[];if(['campus','facility'].includes(state.scale)){drawPhysical(c,w,h);return;}const flat=['region','metro'].includes(state.scale);const project=(lon,lat)=>flat?flatPoint(lon,lat,w,h):projectPoint(lon,lat,w,h),sphere=project(0,0);c.fillStyle='#081724';c.fillRect(0,0,w,h);for(let i=0;i<95;i++){c.fillStyle='#6ea9b21c';c.fillRect((i*7717%997)/997*w,(i*4199%991)/991*h,.6,.6);}if(!flat){const halo=c.createRadialGradient(sphere.cx,sphere.cy,sphere.r*.88,sphere.cx,sphere.cy,sphere.r*1.19);halo.addColorStop(0,'#77dcca00');halo.addColorStop(.55,'#6be4c642');halo.addColorStop(1,'#5ddcc000');c.fillStyle=halo;c.beginPath();c.arc(sphere.cx,sphere.cy,sphere.r*1.19,0,Math.PI*2);c.fill();c.save();c.beginPath();c.arc(sphere.cx,sphere.cy,sphere.r,0,Math.PI*2);c.clip();const sea=c.createRadialGradient(sphere.cx-sphere.r*.25,sphere.cy-sphere.r*.4,0,sphere.cx,sphere.cy,sphere.r*1.3);sea.addColorStop(0,'#153b44');sea.addColorStop(.6,'#0c2936');sea.addColorStop(1,'#06111e');c.fillStyle=sea;c.fillRect(0,0,w,h);}const line=(coords,color,width)=>{c.beginPath();let running=false;for(const [lon,lat]of coords){const p=project(lon,lat);if(p.z<=.01||p.x<-30||p.x>w+30||p.y<-30||p.y>h+30){running=false;continue;}if(running)c.lineTo(p.x,p.y);else c.moveTo(p.x,p.y);running=true;}c.strokeStyle=color;c.lineWidth=width;c.stroke();};if(!flat){for(const [lon,lat]of DATA.world.dots){const p=project(lon,lat);if(p.z>0){c.fillStyle='rgba(109,172,177,'+(.2+p.z*.34)+')';c.fillRect(p.x,p.y,.8,.8);}}for(let lo=-180;lo<=180;lo+=30)line(Array.from({length:81},(_,i)=>[lo,-80+i*2]),'#5d8a9720',.5);for(let la=-60;la<=60;la+=30)line(Array.from({length:121},(_,i)=>[-180+i*3,la]),'#5d8a9720',.5);}DATA.world.lines.forEach(l=>line(l,flat?'#416474':'#5e9fa77a',flat?.8:.55));if(flat){DATA.states.forEach(l=>line(l,'#5a828c55',.6));DATA.roads.forEach(l=>line(l,'#78969455',.65));DATA.lakes.forEach(l=>line(l,'#8abfc188',1));}if(!flat){c.restore();c.strokeStyle='#8cb6b249';c.lineWidth=.7;c.beginPath();c.arc(sphere.cx,sphere.cy,sphere.r,0,Math.PI*2);c.stroke();}if(memory.layers.locations){c.fillStyle='#d1deda85';for(const r of DATA.locations){const p=project(r.lon,r.lat);if(p.z>.03&&p.x>8&&p.x<w-8&&p.y>55&&p.y<h-50){c.beginPath();c.arc(p.x,p.y,flat?1.2:.65,0,Math.PI*2);c.fill();}}}const points=(memory.layers.research?scope():[]).map(s=>({s,p:project(s.lon,s.lat),mw:known(s,state.phase)?s[state.phase].it_mw:null})).filter(r=>r.p.z>.025&&r.p.x>13&&r.p.x<w-13&&r.p.y>92&&r.p.y<h-85);const groups=[];for(const point of points.slice().sort((a,b)=>(b.mw||0)-(a.mw||0))){const near=!flat&&groups.find(g=>Math.hypot(g.x-point.p.x,g.y-point.p.y)<24);if(near){near.members.push(point);near.x=near.members.reduce((n,s)=>n+s.p.x,0)/near.members.length;near.y=near.members.reduce((n,s)=>n+s.p.y,0)/near.members.length;}else groups.push({x:point.p.x,y:point.p.y,members:[point]});}groups.forEach(g=>{g.mw=g.members.reduce((n,m)=>n+(m.mw||0),0);g.native=g.members.every(m=>m.mw==null);g.selected=g.members.some(m=>m.s.id===state.site);g.r=Math.max(g.native?4:5,Math.min(flat?19:24,3+Math.sqrt(g.mw)*.35));const color=g.native?'#b5a1ff':g.members.some(m=>m.s.review==='reviewed-model')?'#99edca':'#8bbcf7';const glow=c.createRadialGradient(g.x,g.y,0,g.x,g.y,g.r*3);glow.addColorStop(0,color+'60');glow.addColorStop(.5,color+'20');glow.addColorStop(1,color+'00');c.fillStyle=glow;c.beginPath();c.arc(g.x,g.y,g.r*3,0,Math.PI*2);c.fill();c.strokeStyle=color;c.fillStyle=color+(g.selected?'60':'25');c.lineWidth=g.selected?1.6:.8;c.beginPath();c.arc(g.x,g.y,g.r,0,Math.PI*2);c.fill();c.stroke();c.fillStyle='#d7fff0';c.beginPath();c.arc(g.x,g.y,1.6,0,Math.PI*2);c.fill();drawn.push({x:g.x,y:g.y,r:g.r+9,site:g.members.find(m=>m.s.id===state.site)?.s.id||g.members[0].s.id});});const occupied=[];if(memory.layers.labels){for(const g of groups.slice().sort((a,b)=>Number(b.selected)-Number(a.selected)||b.mw-a.mw)){if(occupied.length>=(w<500?2:4))break;let name=flat?g.members[0].s.name:g.native?g.members[0].s.country:g.members.length>1?(region(g.members[0].s)==='North America'?'US '+(g.members[0].s.lon<-106?'West':g.members[0].s.lon<-97&&g.members[0].s.lat<38?'South':'East & Midwest'):'Europe')+' cluster':g.members[0].s.name;if(name.length>26)name=name.slice(0,24)+'…';const sub=g.native?'Native / unquantified':(g.mw>=1000?fmt(g.mw/1000,2)+' GW':fmt(g.mw)+' MW')+' · '+g.members.filter(m=>m.mw!=null).length+' estimates';c.font='10px -apple-system,sans-serif';const bw=Math.max(c.measureText(name).width,c.measureText(sub).width)+14,bh=34;const boxes=[{x:g.x+g.r+9,y:g.y-13},{x:g.x-g.r-bw-9,y:g.y-13},{x:g.x-bw/2,y:g.y+g.r+9}];const b=boxes.find(b=>b.x>8&&b.x+bw<w-8&&b.y>96&&b.y+bh<h-92&&!occupied.some(a=>b.x<a.x+a.w+7&&b.x+bw+7>a.x&&b.y<a.y+a.h+6&&b.y+bh+6>a.y)&&!groups.some(x=>Math.hypot(x.x-Math.max(b.x,Math.min(x.x,b.x+bw)),x.y-Math.max(b.y,Math.min(x.y,b.y+bh)))<x.r+4));if(!b)continue;c.fillStyle='#081e29e8';c.fillRect(b.x,b.y,bw,bh);c.strokeStyle='#395761';c.lineWidth=.5;c.strokeRect(b.x,b.y,bw,bh);c.fillStyle='#e0f0ee';c.fillText(name,b.x+7,b.y+13);c.font='8px ui-monospace,monospace';c.fillStyle='#88b4c1';c.fillText(sub,b.x+7,b.y+26);occupied.push({...b,w:bw,h:bh});}}if(flat&&memory.layers.labels){c.font='10px -apple-system,sans-serif';for(const place of DATA.places.slice().sort((a,b)=>a.rank-b.rank)){const p=project(place.lon,place.lat);if(p.x<20||p.x>w-80||p.y<110||p.y>h-90||occupied.some(a=>p.x<a.x+a.w+35&&p.x+70>a.x&&p.y<a.y+a.h+15&&p.y+15>a.y))continue;c.fillStyle='#a3bdc5';c.fillText(place.name,p.x+5,p.y-4);c.fillStyle='#7fa1a9';c.fillRect(p.x,p.y,2,2);occupied.push({x:p.x,y:p.y-15,w:70,h:18});if(occupied.length>8)break;}}if(memory.layers.electricity){c.fillStyle='#dac18b';c.font='9px -apple-system,sans-serif';c.fillText('Electricity: bounded campus captures only. Open a physical scene.',16,h-102);}syncMarkers();}
function drawPhysical(c,w,h){const m=scene();if(!m){c.fillStyle='#0d2331';c.fillRect(0,0,w,h);c.fillStyle='#9ab2be';c.font='13px sans-serif';c.fillText('Historical imagery not established for this project.',20,h*.5);return;}let image=images.get(m.id);if(!image){image=new Image();images.set(m.id,image);image.onload=drawMap;image.src=m.image.embedded;}if(!image.complete)return;const f=feature();let zoom=camera?.zoom||1,base=Math.min(w/image.width,(h-40)/image.height);if(state.scale==='facility'&&f&&!camera){const xs=f.pixel_vertices.map(v=>v[0]),ys=f.pixel_vertices.map(v=>v[1]);base=Math.min((w-140)/(Math.max(...xs)-Math.min(...xs)),(h-145)/(Math.max(...ys)-Math.min(...ys)));}const scale=base*zoom,fx=f&&state.scale==='facility'?(Math.min(...f.pixel_vertices.map(v=>v[0]))+Math.max(...f.pixel_vertices.map(v=>v[0])))/2:image.width/2,fy=f&&state.scale==='facility'?(Math.min(...f.pixel_vertices.map(v=>v[1]))+Math.max(...f.pixel_vertices.map(v=>v[1])))/2:image.height/2,ox=w*.5-fx*scale,oy=h*.51-fy*scale;c.fillStyle='#091b23';c.fillRect(0,0,w,h);c.drawImage(image,ox,oy,image.width*scale,image.height*scale);c.fillStyle='#05142040';c.fillRect(0,0,w,h);for(const roof of m.features){const selected=roof.id===f?.id;c.beginPath();roof.pixel_vertices.forEach(([x,y],i)=>i?c.lineTo(ox+x*scale,oy+y*scale):c.moveTo(ox+x*scale,oy+y*scale));c.closePath();c.fillStyle=selected?'#93efd443':'#89adf719';c.strokeStyle=selected?'#b5ffe3':'#93b7e8';c.lineWidth=selected?2.1:1.2;c.shadowColor=selected?'#9ef7d4':'#6c9cec';c.shadowBlur=selected?12:3;c.fill();c.stroke();c.shadowBlur=0;const px=roof.pixel_vertices.reduce((n,v)=>n+v[0],0)/roof.pixel_vertices.length,py=roof.pixel_vertices.reduce((n,v)=>n+v[1],0)/roof.pixel_vertices.length;const x=ox+px*scale,y=oy+py*scale;drawn.push({x,y,r:Math.max(20,Math.sqrt(roof.derived_outline_area?.rounded_m2||0)*scale),feature:roof.id,vertices:roof.pixel_vertices.map(([x,y])=>[ox+x*scale,oy+y*scale])});if(memory.layers.labels&&w>450){c.font='9px ui-monospace,monospace';const text=roof.name,bw=c.measureText(text).width+14;c.fillStyle='#06151fea';c.fillRect(x-bw/2,y-10,bw,22);c.fillStyle=selected?'#d6ffed':'#c1d8ef';c.fillText(text,x-bw/2+7,y+4);}}if(memory.layers.electricity){c.fillStyle='#122a25ed';c.fillRect(15,98,Math.min(300,w-30),43);c.font='9px sans-serif';c.fillStyle='#e4c88b';c.fillText('Electricity source context · separate capture / edit dates',23,116);c.fillStyle='#a3c3c0';c.fillText('Designed layer: native objects, voltage, sources & export',23,131);}syncMarkers();}
function syncMarkers(){const layer=document.getElementById('marker-layer');if(!layer)return;layer.innerHTML=drawn.map(g=>`<button class="marker-button" style="left:${g.x}px;top:${g.y}px" ${g.feature?'data-feature="'+g.feature+'"':'data-project="'+g.site+'"'} aria-label="${esc(g.feature?scene().features.find(f=>f.id===g.feature)?.name:DATA.sites.find(s=>s.id===g.site)?.name)}"></button>`).join('');}
function panel(kind,id){memory.panel=kind;let body='',title='',kicker='DESIGN PREVIEW / IN-MEMORY INTERACTIONS';if(kind==='search'){title='Find a project or source.';body='<p>Search the dated research collection. Pick a result to inspect its place in the atlas.</p><input class="search-input" id="design-search" placeholder="New Carlisle, Helios, Galaxy…" aria-label="Search projects and sources"><div id="search-results"></div>';}else if(kind==='filters'){title='Refine the research view.';body=`<p>These refinements affect the design session. Source collections remain separate.</p><input class="search-input" id="design-filter" value="${esc(state.q)}" placeholder="Project, location or owner"><div class="context-list">${['all',...REGIONS].map(r=>`<button data-region="${r}">${r==='all'?'All geographic scopes':r} ${r===state.region?'✓':''}</button>`).join('')}</div><button class="primary" style="margin-top:20px" data-apply-filter>Apply refinement →</button>`;}else if(kind==='layers'){title='Layers with their sources.';body=`<p>Geographic context, physical features and power claims have separate source boundaries.</p>${[['labels','Project & feature labels','Sparse labels, keyboard selection and exact identities.'],['electricity','Electricity context','Bounded Helios/Edison/SR2 native captures. No worldwide coverage or inferred service.'],['locations','Independent OSM locations','5265 source locations shown as small neutral points; no capacity or reviewed project correspondence.'],['research','Research project anchors','Approximate named-project coordinates; no parcel survey.']].map(([key,label,note])=>`<label class="layer-option"><input type="checkbox" data-layer="${key}" ${memory.layers[key]?'checked':''}><span><b>${label}</b><small>${note}</small></span></label>`).join('')}<div class="planned-feature"><div class="eyebrow">Designed unavailable state</div><h3>Current imagery & fiber.</h3><p>Current licensed imagery and wider fiber coverage need reviewed acquisitions. Each layer will expose date, coverage, rights, native sources and an explicit availability state.</p><button class="pill" disabled>Source acquisition required</button></div>`;}else if(kind==='compare'){title='Compare the same boundary.';const projects=memory.compare.map(id=>DATA.sites.find(s=>s.id===id));body='<p>Independent estimates retain their dates. Project and building scope stay separate.</p><table class="comparison-table"><thead><tr><th>Dimension</th>'+projects.map(s=>'<th>'+esc(s.name)+'</th>').join('')+'</tr></thead><tbody>'+[['Snapshot model',s=>modelPower(s,'snapshot','MW IT')+'<small>'+esc(s.snapshot?.date)+'</small>'],['Target model',s=>modelPower(s,'target','MW IT')+'<small>'+esc(s.target?.date)+'</small>'],['Historical image',s=>esc(DATA.scenes.find(m=>m.project_id===s.id)?.image.acquired_at||'Unavailable')],['Building-to-phase match',s=>'Not established'],['Owner / operator',s=>esc(s.owner_label)]].map(([label,value])=>'<tr><th>'+label+'</th>'+projects.map(s=>'<td>'+value(s)+'</td>').join('')+'</tr>').join('')+'</tbody></table><p style="margin-top:18px;font-size:11px">No aggregate of these columns is implied. A cited export is designed for implementation.</p>';}else if(kind==='sources'||kind==='source'){const s=source(id);title=s?s.title:project().name+' — source desk.';body=s?`<p>${esc(s.publisher)} · ${esc(s.published_at||'Publication date not stated')}</p><a class="primary" style="margin:20px 0" href="${esc(s.url)}" target="_blank" rel="noopener">Open original document ↗</a><div class="eyebrow">Reviewed project claims</div>${DATA.observations.filter(r=>r.source_id===id&&r.site_id===state.site).map(r=>`<div class="claim"><b>${esc(r.scope)} · ${fmt(r.value)} ${esc(r.unit)}</b><p>${esc(r.boundary)} · ${esc(r.status)} · ${esc(r.as_of)}</p><p>${esc(r.qualifier)}</p></div>`).join('')||'<p class="empty">Select the original document to inspect its reporting boundary.</p>'}`:`<p>Original publication, retrieval date, claim locator and revision state travel with each record.</p>${sourceRows(sourceIds())}<div class="planned-feature"><div class="eyebrow">Designed missing workflow</div><h3>Compare the source versions.</h3><p>A changed source becomes a proposal. Accepted evidence stays available until a reviewed revision replaces it. A locator, changed claim and reviewer decision appear together.</p><button class="pill" disabled>Revision UI is a design requirement</button></div>`;}else if(kind==='image'){const m=scene(),f=feature();title='A feature with a source.';body=m?`<p>${esc(m.title)} · ${esc(m.image.acquired_at)}</p><img src="${m.image.embedded}" style="width:100%;max-height:260px;object-fit:contain;margin:17px 0" alt="Full historical source scene"><div class="data-row"><span>Publisher</span><b>${esc(m.image.publisher)}</b></div><div class="data-row"><span>License</span><b>${esc(m.image.license)}</b></div><div class="data-row"><span>Interpreted feature</span><b>${esc(f?.name||'No roof selected')}</b></div><div class="data-row"><span>Phase / IT allocation</span><b>Not established</b></div><p style="margin-top:17px;font-size:11px;overflow-wrap:anywhere">Image SHA-256: ${esc(m.image.sha256)}</p><p style="margin-top:15px">${esc(m.review.limitations)}</p><a class="text-link" href="${esc(m.image.metadata_url||m.image.export_url)}" target="_blank" rel="noopener">Original image metadata ↗</a>`:'<p>Accepted imagery is unavailable for this project. Project-level source evidence remains accessible.</p>';}else if(kind==='relationships'||kind==='companies'){title='Who does what at this project?';body=`<p>Reported relationships have a role, date and source. Co-location and proximity do not create a reviewed relationship.</p>${DATA.relationships.filter(r=>r.site_id===state.site&&r.review_status==='accepted').map(r=>`<div class="claim"><b>${esc(DATA.companies.find(c=>c.id===r.company_id)?.name||r.company_id)}</b><p>${esc(r.role)} · ${esc(r.as_of)}</p><button class="text-link" data-source="${esc(r.source_id)}">${esc(r.source_id)} · original source ↗</button></div>`).join('')||'<p class="empty">No accepted role in this prototype subset.</p>'}<div class="planned-feature"><div class="eyebrow">Designed company context</div><p>Company spending, backlog and lease obligations occupy their own dated financial view. They are never substituted for campus spending or IT capacity.</p></div>`;}else if(kind==='investment'){title='Capital retains its own scope.';const rows=DATA.observations.filter(r=>r.site_id===state.site&&['cost','investment','lease_term'].includes(r.metric));body='<p>Company investment, campus construction, a lease term and an independent replacement model are different measurements.</p>'+rows.map(r=>`<div class="claim"><b>${esc(r.scope)}</b><p>${fmt(r.value)} ${esc(r.unit)} · ${esc(r.as_of)}</p><p>${esc(r.qualifier)}</p><button class="text-link" data-source="${r.source_id}">Read ${r.source_id} ↗</button></div>`).join('')+'<div class="planned-feature"><div class="eyebrow">Designed missing financial view</div><p>A linked company panel will compare dated capex, financing and obligations separately from named site estimates. Native units and source locators are required.</p></div>';}else if(kind==='inventory'){title='One place. Separate inventories.';body=`<p>The ${fmt(DATA.catalog_count)} OSM location records and ${DATA.sites.length} research projects are independent collections.</p><div class="identity-trail"><span>Research project</span><span>OSM native object</span><span>Operator directory</span><span>Publisher directory</span></div><div class="planned-feature"><div class="eyebrow">Designed identity review</div><h3>Propose → inspect → review.</h3><p>Compare a name, address, native version and source document side by side. Distinguish a named-facility correspondence from campus membership or nearby context.</p><div class="data-row"><span>New Carlisle project → roofs</span><b>Historical interpretation</b></div><div class="data-row"><span>Roof → numbered phase / IT</span><b>Unmatched</b></div><button class="pill" style="margin-top:14px" disabled>Editorial review not implemented</button></div>`;}else if(kind==='shelf'){title='Your research shelf.';body='<p>Design session only. These selections do not write browser storage or evidence.</p>'+memory.shelf.map(id=>{const s=DATA.sites.find(s=>s.id===id);return '<button class="search-result" data-preview="'+id+'"><strong>'+esc(s.name)+'</strong><span>'+esc(s.location)+'</span></button>';}).join('')+(memory.shelf.length?'':'<p class="empty">Add a campus to see it here.</p>');}else if(kind==='share'){title='A link to this exact view.';body='<p>Scale, project, region, estimate layer and selected roof are restored from the design URL.</p><input class="search-input" readonly aria-label="Design URL" value="'+esc(location.href)+'"><p>Private notes, shelf and comparison state remain in this design session.</p>';}else if(kind==='review'){title='Design direction & missing features.';body='<p><b>A · Editorial atlas</b> is the closest match to the original six references: geographic narrative, selected dossier and physical evidence, with four summary metrics along the lower edge.</p><div class="claim"><b>B · Evidence desk</b><p>Records and comparison first. A smaller contextual map supports repeated research.</p></div><div class="claim"><b>C · Map focus</b><p>Immersive geographic discovery. The selected project becomes a floating sheet.</p></div><div class="planned-feature"><div class="eyebrow">Open design requirements</div><p>Reviewed building/phase matches; current licensed imagery; cross-inventory review; source revision comparison; typed financial views; fiber coverage; recoverable loading and exact source-version routes.</p></div><p style="margin-top:20px">This study demonstrates the visual and interaction design. It does not publish evidence or implement the missing workflows.</p><pre style="font-size:10px;white-space:pre-wrap;color:#90b5b8;margin-top:20px">'+esc(JSON.stringify({view:state,session:memory},null,2))+'</pre>';}else{title='Read the atlas with its boundaries.';body=`<p>${DATA.sites.length} named research projects, ${DATA.sites.filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon)).length} approximate map anchors and ${fmt(DATA.catalog_count)} independent OSM locations. This is a dated collection, not a global compute census.</p><h3>Three kinds of evidence.</h3><div class="claim"><b>Independent models</b><p>Snapshot and target IT estimates retain dates and are not summed as increments.</p></div><div class="claim"><b>Primary project disclosures</b><p>Delivered, contracted, approved, gross and IT quantities remain separate.</p></div><div class="claim"><b>Historical physical features</b><p>A roof outline does not establish current operations, height, parcel ownership or a phase/IT allocation.</p></div>`;}document.getElementById('panel-root').innerHTML=`<div class="panel-backdrop"><section class="design-panel" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="panel-head"><span class="eyebrow">${kicker}</span><button data-close aria-label="Close design panel">×</button></header><h1>${title}</h1>${body}</section></div>`;document.querySelector('.design-panel [data-close]')?.focus();if(kind==='search'){searchResults('');document.getElementById('design-search').focus();}reviewBar();}
function searchResults(q){const host=document.getElementById('search-results');if(!host)return;const needle=q.toLowerCase();const rows=DATA.sites.filter(s=>(s.name+' '+s.location+' '+s.owner_label).toLowerCase().includes(needle)).slice(0,8);host.innerHTML=rows.map(s=>`<button class="search-result" data-project="${s.id}"><strong>${esc(s.name)}</strong><span>${esc(s.location)} · ${esc(s.owner_label)}</span></button>`).join('')||'<p class="empty">No matching project in the dated research collection.</p>';}
function closePanel(){document.getElementById('panel-root').innerHTML='';memory.panel=null;reviewBar();}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-review-toggle')){const bar=document.getElementById('review-bar');bar.hidden=!bar.hidden;bar.style.display=bar.hidden?'none':'';return;}if(b.hasAttribute('data-close')){closePanel();return;}if(b.hasAttribute('data-menu')){document.querySelector('.sidebar').classList.toggle('mobile-open');return;}if(b.dataset.panel){panel(b.dataset.panel);return;}if(b.dataset.source){panel('source',b.dataset.source);return;}if(b.dataset.variant){go({variant:b.dataset.variant});return;}if(b.dataset.variantArrow){const keys=Object.keys(NAMES),i=(keys.indexOf(state.variant)+Number(b.dataset.variantArrow)+3)%3;go({variant:keys[i]});return;}if(b.dataset.scale){const update={scale:b.dataset.scale,inspect:false,feature:''};if(b.dataset.scale==='facility'&&!scene())update.site=HELIOS;go(update);return;}if(b.dataset.phase){go({phase:b.dataset.phase});return;}if(b.dataset.region){go({region:b.dataset.region,inspect:false});return;}if(b.dataset.regionalEntry){go({scale:'continent',region:b.dataset.regionalEntry,inspect:false});return;}if(b.dataset.project){go({site:b.dataset.project,inspect:true,feature:'',scene:''});return;}if(b.dataset.preview){go({scale:'campus',site:b.dataset.preview,scene:'',feature:'',inspect:true});return;}if(b.dataset.feature){go({feature:b.dataset.feature,scale:'facility',inspect:true});return;}if(b.dataset.topic){memory.topic=b.dataset.topic;render();return;}if(b.hasAttribute('data-save')){memory.shelf=memory.shelf.includes(state.site)?memory.shelf.filter(id=>id!==state.site):[...memory.shelf,state.site];render();return;}if(b.hasAttribute('data-compare-add')){if(!memory.compare.includes(state.site))memory.compare=[...memory.compare,state.site].slice(-3);panel('compare');return;}if(b.hasAttribute('data-labels')){memory.layers.labels=!memory.layers.labels;drawMap();return;}if(b.dataset.zoom){camera={...(camera||{}),zoom:(camera?.zoom||1)*(b.dataset.zoom==='in'?1.2:1/1.2)};drawMap();return;}if(b.hasAttribute('data-frame')){camera=null;drawMap();return;}if(b.hasAttribute('data-tour')){go({scale:state.scale==='world'?'continent':state.scale==='continent'?'region':state.scale==='region'?'metro':'campus',region:'all',site:NC,inspect:false});return;}if(b.hasAttribute('data-apply-filter')){go({q:document.getElementById('design-filter').value});return;}});
document.addEventListener('change',event=>{if(event.target.matches('[data-component]'))go({scene:event.target.value,feature:''});if(event.target.matches('[data-layer]')){memory.layers[event.target.dataset.layer]=event.target.checked;drawMap();reviewBar();}});
document.addEventListener('input',event=>{if(event.target.id==='design-search')searchResults(event.target.value);if(event.target.matches('[data-note]'))memory.notes[state.site]=event.target.value;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closePanel();return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();panel('search');return;}if(event.target.closest('input,textarea,select,[contenteditable],canvas'))return;if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const keys=Object.keys(NAMES),i=(keys.indexOf(state.variant)+(event.key==='ArrowRight'?1:-1)+3)%3;go({variant:keys[i]});}});
document.addEventListener('pointerdown',event=>{if(event.target.id!=='design-map'||['region','metro','campus','facility'].includes(state.scale))return;drag={x:event.clientX,lon:camera?.lon??-35};event.target.setPointerCapture(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!drag)return;camera={...(camera||{}),lon:drag.lon-(event.clientX-drag.x)*.25};drawMap();});
document.addEventListener('pointerup',()=>drag=null);
window.addEventListener('resize',drawMap);window.addEventListener('popstate',()=>{readState();closePanel();render();});readState();render();
